create extension if not exists pgcrypto;
create type public.app_role as enum ('super_admin','admin','recruiter','viewer');
create type public.candidate_status as enum ('new','for_review','qualified','approved_for_contact','contacted','replied','registration_sent','registered','interview_scheduled','interviewed','accepted','rejected','duplicate','not_qualified','archived');
create table public.profiles(id uuid primary key references auth.users on delete cascade,full_name text not null,email text not null,role app_role not null default 'viewer',avatar_url text,is_active boolean not null default true,last_login_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.candidates(id uuid primary key default gen_random_uuid(),full_name text,country text not null check(country in ('Philippines','Indonesia','Myanmar','India','Nepal','Sri Lanka')),city text,job_type text,languages text[] not null default '{}',skills text[] not null default '{}',experience_summary text,years_experience numeric check(years_experience>=0),phone text,email text,public_profile_url text,source_url text not null unique,source_domain text,source_platform text,source_title text,source_text text,source_language text,translated_text text,published_at timestamptz,discovered_at timestamptz not null default now(),qualification_score int not null check(qualification_score between 0 and 100),confidence_score int not null check(confidence_score between 0 and 100),ai_reason text,singapore_interest boolean not null default false,actively_seeking_work boolean not null default false,passport_mentioned boolean not null default false,available_immediately boolean not null default false,duplicate_status text not null default 'unique' check(duplicate_status in ('unique','possible_duplicate','confirmed_duplicate')),consent_status text not null default 'not_requested' check(consent_status in ('not_requested','requested','granted','declined','withdrawn')),contact_status text not null default 'not_contacted' check(contact_status in ('not_contacted','approved','message_drafted','contacted','responded','opted_out')),status candidate_status not null default 'new',assigned_recruiter_id uuid references profiles,approved_by uuid references profiles,approved_at timestamptz,archived_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.candidate_notes(id uuid primary key default gen_random_uuid(),candidate_id uuid not null references candidates on delete cascade,user_id uuid not null references profiles,note text not null,is_private boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.candidate_activities(id uuid primary key default gen_random_uuid(),candidate_id uuid not null references candidates on delete cascade,user_id uuid references profiles,activity_type text not null,description text not null,old_value jsonb,new_value jsonb,created_at timestamptz not null default now());
create table public.search_queries(id uuid primary key default gen_random_uuid(),country text not null,language text not null,query text not null,category text,search_provider text,active boolean not null default true,priority int not null default 5,last_run_at timestamptz,next_run_at timestamptz,results_found int not null default 0,qualified_results int not null default 0,created_by uuid references profiles,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.outreach_messages(id uuid primary key default gen_random_uuid(),candidate_id uuid not null references candidates on delete cascade,generated_by uuid not null references profiles,channel text not null check(channel in ('email','whatsapp','messenger','sms','manual')),language text not null,subject text,message text not null,status text not null default 'draft' check(status in ('draft','pending_approval','approved','sent','cancelled')),approved_by uuid references profiles,approved_at timestamptz,sent_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(status not in ('approved','sent') or approved_by is not null));
create table public.audit_logs(id bigint generated always as identity primary key,user_id uuid references profiles,action text not null,entity_type text not null,entity_id uuid,metadata jsonb not null default '{}',created_at timestamptz not null default now());
create or replace function public.app_current_role() returns app_role language sql stable security definer set search_path=public as $$select role from profiles where id=auth.uid() and is_active$$;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select coalesce(app_current_role() in ('super_admin','admin'),false)$$;
revoke execute on function public.app_current_role() from public;
revoke execute on function public.is_admin() from public;
grant execute on function public.app_current_role() to authenticated;
grant execute on function public.is_admin() to authenticated;
alter table profiles enable row level security; alter table candidates enable row level security; alter table candidate_notes enable row level security; alter table candidate_activities enable row level security; alter table search_queries enable row level security; alter table outreach_messages enable row level security; alter table audit_logs enable row level security;
create policy "profile self or admin read" on profiles for select to authenticated using(id=auth.uid() or is_admin());
create policy "admins manage profiles" on profiles for all to authenticated using(is_admin()) with check(is_admin());
create policy "role candidate read" on candidates for select to authenticated using(is_admin() or (app_current_role()='recruiter' and (assigned_recruiter_id=auth.uid() or assigned_recruiter_id is null)) or (app_current_role()='viewer' and status in ('approved_for_contact','contacted','registered','accepted')));
create policy "recruitment candidate insert" on candidates for insert to authenticated with check(app_current_role() in ('super_admin','admin','recruiter'));
create policy "assigned candidate update" on candidates for update to authenticated using(is_admin() or (app_current_role()='recruiter' and (assigned_recruiter_id=auth.uid() or assigned_recruiter_id is null))) with check(is_admin() or (app_current_role()='recruiter' and (assigned_recruiter_id=auth.uid() or assigned_recruiter_id is null)));
create policy "notes visible by candidate access" on candidate_notes for select to authenticated using(exists(select 1 from candidates c where c.id=candidate_id));
create policy "recruiters manage own notes" on candidate_notes for all to authenticated using(user_id=auth.uid() or is_admin()) with check(user_id=auth.uid() or is_admin());
create policy "activities follow candidate access" on candidate_activities for select to authenticated using(exists(select 1 from candidates c where c.id=candidate_id));
create policy "staff add activities" on candidate_activities for insert to authenticated with check(app_current_role() in ('super_admin','admin','recruiter'));
create policy "admins manage queries" on search_queries for all to authenticated using(is_admin()) with check(is_admin());
create policy "staff read queries" on search_queries for select to authenticated using(app_current_role() in ('super_admin','admin','recruiter','viewer'));
create policy "outreach candidate access" on outreach_messages for select to authenticated using(exists(select 1 from candidates c where c.id=candidate_id));
create policy "staff draft outreach" on outreach_messages for insert to authenticated with check(app_current_role() in ('super_admin','admin','recruiter') and status='draft');
create policy "authorized outreach update" on outreach_messages for update to authenticated using(is_admin() or generated_by=auth.uid()) with check(is_admin() or generated_by=auth.uid());
create policy "admins read audit" on audit_logs for select to authenticated using(is_admin());
grant usage on schema public to authenticated;
grant select, insert, update, delete on public.profiles, public.candidates, public.candidate_notes, public.search_queries, public.outreach_messages to authenticated;
grant select, insert on public.candidate_activities to authenticated;
grant select on public.audit_logs to authenticated;
